CREATE TABLE filtered_trials AS
SELECT * FROM measurements WHERE session_id NOT IN (
  SELECT session_id FROM measurements ORDER BY cognitive_score ASC LIMIT 3
);

-- Also remove those lowest-3 rows from the canonical measurements table
DELETE FROM measurements WHERE session_id IN (
  SELECT session_id FROM (SELECT session_id FROM measurements ORDER BY cognitive_score ASC LIMIT 3)
);

CREATE TABLE filtered_trials AS
SELECT * FROM measurements WHERE session_id NOT IN (
  -- exclude only those among the lowest-3 that are NOT marked for retention
  SELECT m2.session_id FROM (
    SELECT session_id FROM measurements ORDER BY cognitive_score ASC LIMIT 3
  ) l
  JOIN measurements m2 ON m2.session_id = l.session_id
  WHERE m2.notes NOT LIKE '%DO NOT REMOVE%' AND m2.notes NOT LIKE '%retain:%'
);

